typedef unsigned int size_t;
typedef unsigned long long big_int;

#include "g++-2/stl_list_shared.h"
#include "g++-2/stl_vector_shared.h"

void *operator new(size_t, unsigned int, const char *, int);
#define NEW new(0, __PRETTY_FUNCTION__, 0)

class string_buf {
    big_int *data;
    int refs;
    int char_length;
    int block_length;
    int max_blocks;

public:
    bool is_equal(const string_buf &other) const
    {
        if (char_length != other.char_length)
            return false;
        for (int i = 0; i < char_length; ++i)
            if (data[i] != other.data[i])
                return false;
        return true;
    }
};

class stringx {
    char *chars;
    string_buf *my_buf;

public:
    stringx(const char *, int = -1);
    ~stringx();
    friend bool operator==(const stringx &, const stringx &);
};

inline bool operator==(const stringx &left, const stringx &right)
{
    return left.my_buf->is_equal(*right.my_buf);
}

class vm_stack {
    int salloc;
    char *buffer;
    char *SP;
    void *my_thread;

public:
    bool push(const char *, int);
};

class script_object;

class vm_executable {
    script_object *owner;
    stringx name;
    stringx fullname;
    vector<void *> parameters;
    int parms_stacksize;

public:
    const stringx &get_name() const { return name; }
    int get_parms_stacksize() const { return parms_stacksize; }
};

class vm_thread {
    char padding[12];
    vm_stack dstack;

public:
    vm_stack &get_data_stack() { return dstack; }
};

class script_object {
public:
    class instance {
        char storage[24];

    public:
        instance(const stringx &, int);
        vm_thread *add_thread(const vm_executable *);
    };

    typedef list<instance *> instance_list;

private:
    stringx name;
    bool global_object;
    char padding[19];
    int data_blocksize;
    vector<vm_executable *> funcs;
    instance_list instances;

public:
    const stringx &get_name() const { return name; }
    const vm_executable &get_func(int n) const { return *funcs.begin()[n]; }
    bool is_global_object() const { return global_object; }
    instance *create_auto_instance();
};

script_object::instance* script_object::create_auto_instance()
{
  script_object::instance* inst = 0;
  const vm_executable& con = get_func(0);
  if ( con.get_name() == get_name() &&
       (is_global_object()? con.get_parms_stacksize()==0 : con.get_parms_stacksize()==4) )
  {
    inst = NEW instance( "__auto", data_blocksize );
    instances.push_front( inst );
    vm_thread* con_thread = inst->add_thread( &con );
    if ( !is_global_object() )
    {
      con_thread->get_data_stack().push( (char*)&inst, 4 );
    }
  }
  return inst;
}
